--
-- Table structure for table `tm_device`
--

DROP TABLE IF EXISTS `tm_device`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tm_device` (
  `dev_id` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `site_id` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dev_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dev_token` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dev_location` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dev_lon` double DEFAULT NULL,
  `dev_lat` double DEFAULT NULL,
  `dev_elv` double DEFAULT NULL,
  `dev_number_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dev_ip` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dev_port` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dev_img` text COLLATE utf8mb4_general_ci,
  `dev_sts` tinyint DEFAULT NULL,
  `dev_created` datetime DEFAULT NULL,
  `dev_update` datetime DEFAULT NULL,
  PRIMARY KEY (`dev_id`),
